import{_ as n,l,o as e,c as i,v as t,p,x as r,d as s,i as m,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"可竞争市场","description":"","frontmatter":{"title":"可竞争市场","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/contestable-markets.md","filePath":"econ/contestable-markets.md","lastUpdated":1789023840000}'),h={name:"econ/contestable-markets.md"};function c(d,a,B,A,C,_){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="可竞争市场" tabindex="-1">可竞争市场 <a class="header-anchor" href="#可竞争市场" aria-label="Permalink to &quot;可竞争市场&quot;">​</a></h1><div class="epigraph"><p>若进入与退出没有沉没成本，潜在进入者可以打了就跑；在位者即使只有一家，也只能要可维持的价格，超额利润站不住。</p><footer>—— 据 Baumol, Contestable Markets, American Economic Review, 1982；Baumol, Panzar and Willig, 1982 整理</footer></div><p><a href="/econ/long-run-entry">上一课</a>（长期进入与零利润）。自由进入把完全竞争的长期 \\(\\pi\\) 赶到零，但那是价格接受、可复制的 U 形 AC。本课不重讲 \\(S_{\\mathrm{SR}}\\) 与整数缝。缺口是：若技术是次加的、市场「自然」只装得下一家，只要沉没进入成本为零，潜在竞争仍可能把价格压到可维持的平均成本。进入威胁替代了实际的 \\(n\\to\\infty\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课的进入者要建厂，工厂一旦落下就有沉没。可竞争把这层拿掉：进入、生产、退出，成本全部可回收，在位者来不及反应。进入者盯住在位价格 \\(p\\)，以略低的价抢走需求，赚完离开。均衡若还有 \\(\\pi\\gt 0\\)，就会被打了就跑。缺口不是再写一次零利润，而是：<strong>零利润现在由潜在进入执行，不要求市场上真的有许多家，也不要求 \\(p=\\mathrm{MC}\\)。</strong></p><p>可维持价格：在位的 \\((p,q)\\) 使任何进入计划都不能在 \\(p\\) 上赚到正利润，同时在位者自己不亏。自然垄断的次加成本下，可维持往往是 \\(p=\\mathrm{AC}\\) 的拉姆齐式平均成本价，而不是 \\(p=\\mathrm{MC}\\)（MC 在 AC 下方时会亏）。</p><h3 id="可竞争不是完全竞争换了名字" tabindex="-1">可竞争不是完全竞争换了名字 <a class="header-anchor" href="#可竞争不是完全竞争换了名字" aria-label="Permalink to &quot;可竞争不是完全竞争换了名字&quot;">​</a></h3><p>完全竞争要价格接受加许多家实际在产。可竞争允许一家，但要求进入成本不沉没、在位价格被进入者当成参数。没有这两条，一家就是<a href="/econ/monopoly-lerner">垄断</a>。沉没一旦为正，打了就跑的成本收不回，威胁空了——上一课把沉没写成壁垒高度，本课取零这个极点。</p><p><span class="marginnote">Baumol–Panzar–Willig 的「可维持」比「\\(\\pi=0\\)」更紧：多产品时还要挡住只挑肥产品的进入。弱看不见的手：可维持配置在凸性下接近有效，但次加性下 \\(p=\\mathrm{MC}\\) 不可维持。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：进入时滞为零、沉没为零、在位者价格在进入发生前锁死（Sylos 式，但这里锁的是「来不及改价」）。结论：均衡必须可维持。单产品自然垄断，可维持意味着 \\(p=\\mathrm{AC}(q)\\)、\\(q=D(p)\\)，经济利润为零。若需求与 AC 的切点在下降段，则 \\(p\\gt \\mathrm{MC}\\)，配置有一阶无谓损失，但仍比不受约束的垄断价低。</p><p>多产品：交叉补贴可能被「挑肥」进入拆掉，可维持要求没有一组产品能被单独进入打穿。这与完全可分配的成本检验相连，本课只钉逻辑，不把会计分摊写完。</p>',12)),(e(),p(E,null,{default:r(()=>[m(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20LR%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E8%87%AA%E7%94%B1%E8%BF%9B%E5%85%A5%EF%BC%8C%E8%AE%B8%E5%A4%9A%E5%AE%B6%EF%BC%8C%CF%80%20%3D%200%22%5D%20--%3E%20SUNK%5B%22%E6%9C%AC%E8%AF%BE%EF%BC%9A%E6%B2%89%E6%B2%A1%20%3D%200%EF%BC%8C%E5%8F%AF%E4%B8%80%E5%AE%B6%22%5D%0A%20%20SUNK%20--%3E%20HIT%5B%22%E6%89%93%E4%BA%86%E5%B0%B1%E8%B7%91%22%5D%0A%20%20HIT%20--%3E%20SUS%5B%22%E5%8F%AF%E7%BB%B4%E6%8C%81%EF%BC%9Ap%20%E8%B4%B4%E8%BF%91%20AC%22%5D%0A%20%20SUS%20--%3E%20MON%5B%22%E6%B2%89%E6%B2%A1%20%3E%200%EF%BC%9A%E5%9B%9E%E5%88%B0%E5%9E%84%E6%96%AD%E8%AF%BE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要把「潜在进入」写成限价：限价是在位者主动压产；可竞争是进入技术把在位者的可行价格集切掉。工具不同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>威胁的机制是可逆性：进入者与在位者面对同一成本，事后没有「已经沉下去、必须应战」的不对称。在位者若敢要 \\(p\\gt \\mathrm{AC}\\)，进入者按这个 \\(p\\) 算净现值仍为正，于是进。在位者预见到这一点，只能停在可维持边界。</p><p>与<a href="/econ/long-run-entry">长期进入</a>的对照：那里零利润靠 \\(n\\) 真的增加、沿短期供给把 \\(p\\) 压下来；这里 \\(n\\) 可以仍是一，\\(p\\) 被尚未发生的进入钉住。整数缝在可竞争里也更窄：打了就跑不要求第二家长期留下。</p><p>次加成本下 \\(p=\\mathrm{MC}\\) 会亏损，可维持停在 \\(\\mathrm{AC}\\)，与下一课<a href="/econ/natural-monopoly-ramsey">自然垄断的拉姆齐</a>外表像，来源不同：这里没有规制者选逆弹性权，是潜在进入把可行价格切到平均成本。需求一旦不足以在 \\(\\mathrm{AC}\\) 上出清，可维持集可以空，需要补贴或放弃严格可竞争。</p><p><span class="marginnote">批评的核心是时序：真实进入几乎总有沉没与反应时滞。可竞争是基准，不是对航空、电信的直接描述。沉没一出现，本课的威胁退回<a href="/econ/limit-pricing">限制进入</a>要处理的承诺问题。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>沉没、合同锁期、在位者瞬时改价，都会拆掉「打了就跑」。规制用可竞争当参照时，要先问进入的可逆性，不能看见一家就自动允许平均成本定价。多产品可维持集可能空，需要补贴或放弃严格可维持。</p><p>航空、电信常被拿来当例子，也是最早的反例：航线有机队与机场槽位沉没，在位者可以瞬时改价。用可竞争去放松规制，必须先核对这两条，不能看见「进出相对自由」就写成定理。</p><p>下一课撤掉潜在进入与价格接受，面对向下的 \\(P(Q)\\)，用勒纳指数读垄断势力。本课的教训是：家数不等于势力；势力还要看进入的沉没。</p><p>后课默认：沉没为零时，即使一家，可维持价格把超额利润赶走；沉没为正，潜在竞争不再等价于实际竞争。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可竞争把零利润交给潜在进入，不要求许多家在产。</li><li>沉没为零、进入可逆，是威胁可信的前提。</li><li>可维持可以是 \\(p=\\mathrm{AC}\\) 而不是 \\(p=\\mathrm{MC}\\)。</li><li>下一课：进入挡住之后，一家面对市场需求。</li><li>出处：Baumol, <em>AER</em>, 1982；Baumol, Panzar and Willig, 1982。</li></ul>',13))])}const b=n(h,[["render",c]]);export{f as __pageData,b as default};
